<section class="owner-section-page owner-page"><div class="page-heading"><span class="eyebrow">إدارة الأعضاء</span><h1>المستخدمون والاشتراكات</h1><p>عيّن الخطط يدويًا، وأدر حالة الحساب والصلاحيات من هذه الصفحة فقط.</p></div><?php require __DIR__.'/owner_nav.php'; ?><section class="dashboard-card admin-create-card"><div class="section-card-heading"><div><span class="card-label">إضافة مباشرة</span><h2>إنشاء حساب</h2></div></div><form method="post" action="/owner/user" class="admin-create-form"><?= csrf_field() ?><input type="hidden" name="action" value="create"><label class="field"><span>الاسم</span><input name="full_name" required maxlength="120"></label><label class="field"><span>البريد</span><input type="email" name="email" required maxlength="180"></label><label class="field"><span>نوع الحساب</span><select name="role"><option value="student">طالب</option><option value="teacher">معلم</option></select></label><label class="field"><span>كلمة المرور (12 حرفًا على الأقل)</span><input type="password" name="password" minlength="12" maxlength="72" required></label><button class="button button-gold" type="submit">إنشاء الحساب</button></form></section><section class="dashboard-card admin-toast-card"><div class="section-card-heading"><div><span class="card-label">رسائل فورية</span><h2>إرسال Toast للمستخدمين</h2></div></div><p class="helper-note">يظهر التنبيه تلقائيًا للمستخدمين المتصلين خلال آخر 10 دقائق، أو لحساب محدد.</p><form method="post" action="/owner/notification" class="owner-inline-form"><?= csrf_field() ?><label class="field"><span>المستلم</span><select name="target"><option value="online">المستخدمون المتصلون الآن</option><?php foreach(($users??[]) as $recipient): ?><option value="<?= (int)$recipient['id'] ?>"><?= e($recipient['full_name']) ?> · <?= e($recipient['email']) ?></option><?php endforeach; ?></select></label><label class="field"><span>النوع</span><select name="type"><option value="info">معلومة</option><option value="success">نجاح</option><option value="error">تنبيه</option></select></label><label class="field"><span>العنوان</span><input name="title" maxlength="100" required placeholder="تنبيه من الإدارة"></label><label class="field"><span>الرسالة</span><input name="message" maxlength="500" required placeholder="اكتب الرسالة التي ستظهر كـ Toast"></label><button class="button button-gold" type="submit">إرسال الرسالة</button></form></section><section class="dashboard-card owner-control-card"><div class="section-card-heading"><div><span class="card-label">الحسابات</span><h2><?= count($users??[]) ?> حساب</h2></div></div><p class="helper-note">تغيير الخطة يتم يدويًا من لوحة المالك، ولا يجري تحصيل الأموال إلكترونيًا. الحظر يوقف جلسات الدخول الحالية؛ الحظر المؤقت بالأيام أو الدائم عند إدخال صفر.</p><div class="owner-table-wrap"><table class="owner-table owner-full-table"><thead><tr><th>الحساب</th><th>الحالة</th><th>ملف الإنجاز</th><th>الخطة والمدة</th><th>الإجراءات</th></tr></thead><tbody><?php foreach(($users??[]) as $item): ?><tr><td><strong><?= e($item['full_name']) ?></strong><small><?= e($item['email']) ?></small><?php if((int)$item['is_owner']): ?><span class="owner-badge small">مالك</span><?php endif; ?></td><td><span class="owner-status <?= (int)$item['is_active']?'is-live':'' ?>"><?= (int)$item['is_active']?'نشط':'موقوف' ?></span><?php if(!empty($item['ban_reason'])): ?><span class="owner-ban-badge">حظر: <?= e($item['ban_reason']) ?><?= !empty($item['banned_until'])?' · حتى '.e(saudi_datetime($item['banned_until'])):' · دائم' ?></span><?php endif; ?><small><?= $item['role']==='teacher'?'معلم':'طالب' ?> · <?= e(saudi_datetime($item['created_at'])) ?></small></td><td><strong><?= e(($item['title']??'')?:'لا يوجد ملف') ?></strong><small><?= (int)($item['section_count']??0) ?> أقسام · <?= (int)($item['evidence_count']??0) ?> أدلة · <?= (int)($item['public_view_count']??0) ?> زيارة عامة</small></td><td><span class="owner-plan-pill"><?= e($item['subscription']['name']??'الخطة الأساسية') ?></span><small>السعر: <?= number_format((int)($item['subscription']['price_minor']??0)/100,2) ?> <?= e($item['subscription']['currency']??'SAR') ?></small><small>ينتهي: <?= e(!empty($item['subscription']['subscription_ends_at'])?saudi_datetime($item['subscription']['subscription_ends_at']):'لا يوجد اشتراك مدفوع') ?></small><form method="post" action="/owner/subscription/set" class="form-stack"><?= csrf_field() ?><input type="hidden" name="user_id" value="<?= (int)$item['id'] ?>"><label class="field"><span>الخطة</span><select name="plan_id"><?php foreach(($plans??[]) as $plan): if(!(int)$plan['is_active'])continue; ?><option value="<?= (int)$plan['id'] ?>" <?= (int)($item['subscription']['id']??0)===(int)$plan['id']?'selected':'' ?>><?= e($plan['name']) ?> · <?= number_format((int)$plan['price_minor']/100,2) ?> <?= e($plan['currency']) ?></option><?php endforeach; ?></select></label><label class="field"><span>المدة (يوم)</span><input type="number" name="duration_days" min="1" max="3650" value="30" required></label><label class="field"><span>ملاحظة داخلية</span><input name="admin_note" maxlength="500"></label><button class="text-button" type="submit">تعيين الاشتراك</button></form></td><td><div class="owner-actions"><?php if((int)$item['id']!==(int)$currentUser['id']): ?><form method="post" action="/owner/user"><?= csrf_field() ?><input type="hidden" name="user_id" value="<?= (int)$item['id'] ?>"><input type="hidden" name="action" value="role"><select name="role"><option value="teacher" <?= $item['role']==='teacher'?'selected':'' ?>>معلم</option><option value="student" <?= $item['role']==='student'?'selected':'' ?>>طالب</option></select><button class="text-button" type="submit">حفظ نوع الحساب</button></form><form method="post" action="/owner/user"><?= csrf_field() ?><input type="hidden" name="user_id" value="<?= (int)$item['id'] ?>"><input type="hidden" name="action" value="toggle_active"><button class="text-button" type="submit"><?= (int)$item['is_active']?'تعطيل':'تفعيل' ?> الحساب</button></form><?php endif; ?><?php if(!(int)$item['is_owner']): if(empty($item['ban_reason'])): ?><form method="post" action="/owner/user" class="form-stack"><?= csrf_field() ?><input type="hidden" name="user_id" value="<?= (int)$item['id'] ?>"><input type="hidden" name="action" value="ban"><label class="field"><span>سبب الحظر</span><input name="reason" minlength="5" maxlength="300" required></label><label class="field"><span>أيام (0 = دائم)</span><input type="number" name="days" min="0" max="3650" value="0" required></label><button class="text-button danger-text" type="submit">حظر</button></form><?php else: ?><form method="post" action="/owner/user"><?= csrf_field() ?><input type="hidden" name="user_id" value="<?= (int)$item['id'] ?>"><input type="hidden" name="action" value="unban"><button class="text-button" type="submit">رفع الحظر</button></form><?php endif; ?><form method="post" action="/owner/user"><?= csrf_field() ?><input type="hidden" name="user_id" value="<?= (int)$item['id'] ?>"><input type="hidden" name="action" value="reset_password"><input type="password" name="password" minlength="12" maxlength="72" placeholder="كلمة مرور جديدة" required><button class="text-button" type="submit">تعيين كلمة مرور</button></form><form method="post" action="/owner/user"><?= csrf_field() ?><input type="hidden" name="user_id" value="<?= (int)$item['id'] ?>"><input type="hidden" name="action" value="<?= (int)$item['is_owner']?'demote':'promote' ?>"><button class="text-button" type="submit"><?= (int)$item['is_owner']?'سحب المالك':'منح مالك' ?></button></form><form method="post" action="/owner/user" data-confirm="حذف الحساب ومحتواه نهائيًا؟"><?= csrf_field() ?><input type="hidden" name="user_id" value="<?= (int)$item['id'] ?>"><input type="hidden" name="action" value="delete"><button class="text-button danger-text" type="submit">حذف نهائي</button></form><?php endif; ?></div></td></tr><?php endforeach; if(empty($users)): ?><tr><td colspan="5">لا يوجد مستخدمون بعد.</td></tr><?php endif; ?></tbody></table></div></section></section>
